;jQuery(function(e){const plugin=userfeedback_deactivation.plugin;const name=userfeedback_deactivation.name;const apiUrl=userfeedback_deactivation.api_url;const homeUrl=userfeedback_deactivation.home_url;let $deactivateLink=e('#the-list').find('[data-slug="'+plugin+'"] span.deactivate a'),$overlay=e('#am-deactivate-survey-'+plugin),$form=$overlay.find('form'),formOpen=!1;$deactivateLink.on('click',function(e){e.preventDefault();$overlay.css('display','table');formOpen=!0;$form.find('.am-deactivate-survey-option:first-of-type input[type=radio]').focus()});$form.on('change','input[type=radio]',function(t){t.preventDefault();$form.find('input[type=text], .error').hide();$form.find('.am-deactivate-survey-option').removeClass('selected');e(this).closest('.am-deactivate-survey-option').addClass('selected').find('input[type=text]').show()});$form.on('click','.am-deactivate-survey-deactivate',function(e){e.preventDefault();location.href=$deactivateLink.attr('href')});$form.submit(function(t){t.preventDefault();if(!$form.find('input[type=radio]:checked').val()){$form.find('.am-deactivate-survey-footer').prepend('<span class="error">Please select an option</span>');return};const data={code:$form.find('.selected input[type=radio]').val(),reason:$form.find('.selected .am-deactivate-survey-option-reason').text(),details:$form.find('.selected input[type=text]').val(),site:homeUrl,plugin:name};const submitSurvey=e.post(apiUrl,data);submitSurvey.always(function(){location.href=$deactivateLink.attr('href')})});e(document).keyup(function(e){if(27===e.keyCode&&formOpen){$overlay.hide();formOpen=!1;$deactivateLink.focus()}})});